CREATE TABLE catalog_signals (`product_id` VARCHAR(32) PRIMARY KEY, `handle` VARCHAR(2048), `product_type` VARCHAR(2048), `source_url` VARCHAR(2048), `captured_at_utc` VARCHAR(2048), `option_names` VARCHAR(2048), `variant_count` INT, `numeric_unit_pair` INT, `numeric_range_with_unit` INT, `route_token` INT, `closure_token` INT, `material_token` INT, `size_option_name` INT, `unit_tokens_detected` VARCHAR(2048));
